const fs = require('fs');
const path = require('path');

const items = $input.all();
const item = items[0] || { json: {} };

let fileBuffer = null;
let fileName = 'resume.pdf';
let mimeType = 'application/pdf';
let textContent = null;

const query = (item.json && item.json.query) || {};
const body = (item.json && item.json.body) || {};
const isTest = query.test === 'true' || query.test === true || body.isTest === true || body.test === true || item.json.test === true || item.json.isTest === true;

// 1. Check if file was uploaded via Webhook binary data
if (item.binary && Object.keys(item.binary).length > 0) {
  const binaryKey = Object.keys(item.binary)[0];
  const binObj = item.binary[binaryKey];
  fileName = binObj.fileName || 'uploaded_resume.pdf';
  mimeType = binObj.mimeType || 'application/pdf';
  if (binObj.data) {
    fileBuffer = Buffer.from(binObj.data, 'base64');
  }
}

// 2. Check if a filePath or resumeText was passed via JSON payload
if (!fileBuffer && item.json) {
  if (item.json.resumeText || item.json.text) {
    textContent = item.json.resumeText || item.json.text;
    fileName = 'resume.txt';
    mimeType = 'text/plain';
  } else if (item.json.filePath && fs.existsSync(item.json.filePath)) {
    fileName = path.basename(item.json.filePath);
    fileBuffer = fs.readFileSync(item.json.filePath);
    if (fileName.endsWith('.pdf')) mimeType = 'application/pdf';
    else if (fileName.endsWith('.docx')) mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
    else mimeType = 'text/plain';
  }
}

// 3. Fallback: inspect /data or data/ for candidate resume files
if (!fileBuffer && !textContent) {
  const searchDirs = ['/data', 'data', '/home/node/data'];
  const candidateNames = ['resume_input.pdf', 'resume.pdf', 'resume_final.pdf', 'resume.docx', 'resume.txt', 'resume.md'];

  for (const dir of searchDirs) {
    for (const name of candidateNames) {
      const p = path.join(dir, name);
      if (fs.existsSync(p)) {
        fileName = name;
        fileBuffer = fs.readFileSync(p);
        if (name.endsWith('.pdf')) mimeType = 'application/pdf';
        else if (name.endsWith('.docx')) mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
        else mimeType = 'text/plain';
        break;
      }
    }
    if (fileBuffer) break;
  }
}

if (!fileBuffer && !textContent) {
  throw new Error('No resume file provided or found. Please upload a PDF/DOCX/TXT file or place resume.pdf in /data.');
}

let base64Data = null;
if (mimeType === 'application/pdf' && fileBuffer) {
  base64Data = fileBuffer.toString('base64');
} else if (!textContent && fileBuffer) {
  textContent = fileBuffer.toString('utf8');
}

// Pre-clean textContent to eliminate formatting artifacts (from 01-normalize-resume-text)
if (textContent) {
  textContent = textContent
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\r\n?/g, '\n')
    .replace(/([a-zA-Z0-9])\*+([a-zA-Z0-9])/g, '$1$2')
    .replace(/\*+/g, '')
    .replace(/[ \t]+/g, ' ')
    .split('\n')
    .map(line => line.trim())
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

return [{
  json: {
    fileName,
    mimeType,
    isPdf: mimeType === 'application/pdf',
    base64Data,
    textContent,
    isTest
  }
}];

const SYSTEM_PROMPT = "You are a high-precision resume parsing engine.
Your task is to extract all information from the provided resume and output a valid JSON object matching the exact master-profile schema.

CRITICAL RULES - ZERO FABRICATION & COMPLETE FIDELITY:
1. STRICT ZERO FABRICATION: Do NOT invent, extrapolate, assume, or hallucinate ANY details.
   - Do NOT invent companies, job titles, projects, skills, tools, dates, education, certifications, or metrics.
   - If a field is not present in the resume, use "" for missing strings and [] for missing arrays.
   - Remove markdown or formatting artifacts (such as stray asterisks, bold markers, or malformed spacing); never change the words.
2. NO LOSS OF DETAIL:
   - Copy EVERY SINGLE bullet point, achievement, and responsibility from the resume verbatim or with complete detail. Do NOT summarize or condense.
   - Extract ALL individual skills, tools, platforms, databases, methodologies, and technical keywords.
   - If any skills are labeled with qualifiers like "(Familiar)", "(Beginner)", or "(Prior Experience)", place them in the "skills_familiar" array and list the core/advanced ones in "skills".
   - Extract ALL experience entries. For titles that contain project/division context (e.g. "Data Analyst II — Power Trading & Market Analytics, Wipro"), split the title into "role" (e.g. "Data Analyst II") and "project" (e.g. "Power Trading & Market Analytics").
   - Extract contact details completely: name, email, phone, location, work authorization / residency status (e.g. "Permanent Resident of Canada"), linkedin, github/portfolio if present.
   - For "target_titles": Include a broad list of relevant target roles inferred from the candidate's core functions (e.g. ["Data Analyst", "Data Analyst II", "Senior Data Analyst", "Business Intelligence Analyst", "BI Developer", "Reporting Analyst", "Power BI Developer"]).
   - For "writing_sample": Extract a verbatim 2-4 sentence excerpt from the resume summary or cover letter. Do NOT generate or synthesize a sample.

OUTPUT FORMAT (Return ONLY valid JSON):
{
  "name": "Full Name",
  "target_titles": ["Title 1", "Title 2", "Title 3"],
  "locations": ["Location from resume, e.g. Toronto, ON, Canada"],
  "contact": {
    "email": "email if present or \"\"",
    "phone": "phone if present or \"\"",
    "location": "city/region if present or \"\"",
    "linkedin": "linkedin url if present or \"\"",
    "github": "github url if present or \"\"",
    "status": "residency/visa status if present or \"\""
  },
  "summary": "Professional summary verbatim from resume if present or \"\"",
  "skills": ["Skill 1", "Skill 2"],
  "skills_familiar": ["Familiar Skill 1", "Familiar Skill 2"],
  "experience": [
    {
      "role": "Job Title (e.g. Data Analyst II)",
      "project": "Project / Division if stated (e.g. Power Trading & Market Analytics) or \"\"",
      "company": "Company Name",
      "dates": "Dates e.g. Sep 2025 – Present",
      "bullets": [
        "Verbatim bullet 1 with all metrics and technologies preserved",
        "Verbatim bullet 2 with all metrics and technologies preserved"
      ]
    }
  ],
  "education": [
    {
      "degree": "Degree name",
      "institution": "University / College",
      "dates": "Dates / Graduation Year"
    }
  ],
  "certifications": ["Cert 1", "Cert 2"],
  "projects": [
    {
      "name": "Project Name",
      "description": "Project Description",
      "technologies": ["Tech 1", "Tech 2"]
    }
  ],
  "writing_sample": "Verbatim excerpt only from resume"
}
";

const item = $input.all()[0].json;
const apiKey = $env.GEMINI_API_KEY;
if (!apiKey) throw new Error('GEMINI_API_KEY environment variable is missing.');

let contents = [];
if (item.isPdf && item.base64Data) {
  contents = [{
    parts: [
      { text: SYSTEM_PROMPT },
      { text: "Extract the complete candidate profile from this attached PDF resume. Do NOT fabricate any data. Copy all details verbatim into the JSON structure." },
      {
        inlineData: {
          mimeType: 'application/pdf',
          data: item.base64Data
        }
      }
    ]
  }];
} else {
  contents = [{
    parts: [
      { text: SYSTEM_PROMPT },
      { text: `Extract the complete candidate profile from this resume text:

${item.textContent}

Do NOT fabricate any data. Copy all details verbatim into the JSON structure.` }
    ]
  }];
}

const models = ['gemini-3.5-flash-lite', 'gemini-3.5-flash', 'gemini-flash-lite-latest', 'gemini-flash-latest', 'gemini-3.1-flash-lite', 'gemini-3.7-flash'];
let rawResponse = null;

for (const model of models) {
  try {
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url,
      body: {
        contents,
        generationConfig: { response_mime_type: 'application/json' }
      },
      json: true
    });
    const text = res.candidates?.[0]?.content?.parts?.[0]?.text;
    if (text) {
      rawResponse = text;
      break;
    }
  } catch (e) { continue; }
}

if (!rawResponse) throw new Error('Failed to extract resume with Gemini.');

const cleanText = rawResponse.replace(/```json/gi, '').replace(/```/g, '').trim();
const parsedProfile = JSON.parse(cleanText);

return [{
  json: {
    fileName: item.fileName,
    isTest: item.isTest,
    profile: parsedProfile
  }
}];

const fs = require('fs');
const path = require('path');

const item = $input.all()[0].json;
const profile = item.profile;
const isTest = item.isTest || false;

function cleanStr(str) {
  if (!str || typeof str !== 'string') return '';
  return str
    .replace(/([a-zA-Z0-9])\*+([a-zA-Z0-9])/g, '$1$2')
    .replace(/\*+/g, '')
    .replace(/[\u2013\u2014]/g, '-')
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

function calculateYearsOfExperience(experience = []) {
  if (!Array.isArray(experience) || experience.length === 0) return 0;
  let totalMonths = 0;
  for (const exp of experience) {
    const datesStr = exp.dates || '';
    const match = datesStr.match(/([a-zA-Z]+)?\s*(\d{4})\s*[\u2013\u2014\-–—to]+\s*([a-zA-Z]+)?\s*(\d{4}|present|current)/i);
    if (match) {
      const startYear = parseInt(match[2], 10);
      const endYear = match[4].toLowerCase().includes('pres') || match[4].toLowerCase().includes('curr')
        ? new Date().getFullYear()
        : parseInt(match[4], 10);
      if (!isNaN(startYear) && !isNaN(endYear) && endYear >= startYear) {
        totalMonths += Math.max(12, (endYear - startYear) * 12);
      }
    }
  }
  const years = Math.round(totalMonths / 12);
  return years > 0 ? years : 1;
}

// Clean artifacts from bullets
if (Array.isArray(profile.experience)) {
  for (const exp of profile.experience) {
    if (exp.role) exp.role = cleanStr(exp.role);
    if (exp.company) exp.company = cleanStr(exp.company);
    if (Array.isArray(exp.bullets)) {
      exp.bullets = exp.bullets.map(b => cleanStr(b)).filter(Boolean);
    }
  }
}

// Compute deterministic years of experience
profile.years_of_experience = calculateYearsOfExperience(profile.experience);

const totalBullets = (profile.experience || []).reduce((acc, exp) => acc + (exp.bullets ? exp.bullets.length : 0), 0);

if (isTest) {
  const testPaths = [
    path.join(($env.DATA_DIR || (fs.existsSync('/data') ? '/data' : 'data')), 'test-profile.json'),
    'data/test-profile.json',
    '/home/node/data/test-profile.json'
  ];
  let savedTestPath = null;
  for (const p of testPaths) {
    try {
      const dir = path.dirname(p);
      if (fs.existsSync(dir)) {
        fs.writeFileSync(p, JSON.stringify(profile, null, 2), 'utf8');
        savedTestPath = p;
      }
    } catch(e) {}
  }
  return [{
    json: {
      success: true,
      mode: 'test',
      message: 'Resume parsed and test-profile.json generated successfully. master-profile.json was NOT modified.',
      savedTo: savedTestPath,
      candidate: {
        name: profile.name || 'N/A',
        target_titles: profile.target_titles || [],
        locations: profile.locations || [],
        contact: profile.contact || {},
        years_of_experience: profile.years_of_experience,
        roles_count: (profile.experience || []).length,
        total_bullets: totalBullets,
        skills_count: (profile.skills || []).length,
        education_count: (profile.education || []).length,
        certifications_count: (profile.certifications || []).length
      },
      profile: profile
    }
  }];
}

const targetPaths = [
  path.join(($env.DATA_DIR || (fs.existsSync('/data') ? '/data' : 'data')), 'master-profile.json'),
  'data/profiles/master-profile.json',
  '/home/node/data/profiles/master-profile.json'
];
const backupPaths = [
  path.join(($env.DATA_DIR || (fs.existsSync('/data') ? '/data' : 'data')), 'master-profile.backup.json'),
  'data/profiles/master-profile.backup.json',
  '/home/node/data/profiles/master-profile.backup.json'
];

let savedPath = null;
for (let i = 0; i < targetPaths.length; i++) {
  const p = targetPaths[i];
  const b = backupPaths[i];
  try {
    const dir = path.dirname(p);
    if (fs.existsSync(dir)) {
      if (fs.existsSync(p)) {
        const existing = fs.readFileSync(p, 'utf8');
        fs.writeFileSync(b, existing, 'utf8');
      }
      fs.writeFileSync(p, JSON.stringify(profile, null, 2), 'utf8');
      savedPath = p;
    }
  } catch(e) {}
}

const summary = {
  success: true,
  mode: 'production',
  message: 'Resume parsed and master-profile.json updated successfully with zero fabrication.',
  savedTo: savedPath,
  candidate: {
    name: profile.name || 'N/A',
    target_titles: profile.target_titles || [],
    locations: profile.locations || [],
    contact: profile.contact || {},
    years_of_experience: profile.years_of_experience,
    roles_count: (profile.experience || []).length,
    total_bullets: totalBullets,
    skills_count: (profile.skills || []).length,
    education_count: (profile.education || []).length,
    certifications_count: (profile.certifications || []).length
  }
};

return [{
  json: summary
}];
